CREATE SEQUENCE public.member_access_logs_id_seq;
CREATE TABLE public.intrants (id uuid NOT NULL DEFAULT gen_random_uuid(),cooperative_id uuid NOT NULL,member_id uuid NOT NULL,campagne_id uuid,name text NOT NULL,type text NOT NULL,quantity numeric NOT NULL,unit text NOT NULL,cost_fcfa numeric,purchase_date date DEFAULT CURRENT_DATE,supplier text,created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.member_access_logs (id bigint NOT NULL DEFAULT nextval('member_access_logs_id_seq'::regclass),card_number text,member_id uuid,cooperative_id uuid,fiche_id uuid,action text NOT NULL,created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.parcelles (id uuid NOT NULL DEFAULT gen_random_uuid(),member_id uuid NOT NULL,cooperative_id uuid NOT NULL,culture_principale text,superficie_ha numeric(10,4),created_at timestamp with time zone NOT NULL DEFAULT now(),name text,culture_name text,surface_ha numeric,gps_coordinates text,campaign_year text,source text DEFAULT 'manual'::text,soil_type text,irrigation_type text);
CREATE TABLE public.producer_announcements (id uuid NOT NULL DEFAULT gen_random_uuid(),member_id uuid NOT NULL,cooperative_id uuid,type text NOT NULL,title text NOT NULL,description text,culture text,quantity_kg numeric(12,2),price_per_kg_fcfa numeric(12,2),location_canton text,contact_phone text,status text NOT NULL DEFAULT 'active'::text,created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.productions (id uuid NOT NULL DEFAULT gen_random_uuid(),parcelle_id uuid NOT NULL,campaign text,created_at timestamp with time zone NOT NULL DEFAULT now(),member_id uuid,cooperative_id uuid,culture_name text,quantity_kg numeric,campaign_year text,source text DEFAULT 'manual'::text);
